// Wildmatch implementation: * matches any (including /), ? matches single, [] char class, \ escapes
pub fn wildmatch(pattern: &str, text: &str) -> bool {
    let pat: Vec<char> = pattern.chars().collect();
    let txt: Vec<char> = text.chars().collect();
    do_match(&pat, &txt)
}

fn do_match(pat: &[char], txt: &[char]) -> bool {
    // Recursive with backtracking for *
    // Use indices
    let mut px = 0usize;
    let mut tx = 0usize;
    let mut star_px: Option<usize> = None;
    let mut star_tx: Option<usize> = None;

    while tx < txt.len() {
        if px < pat.len() {
            let pc = pat[px];
            if pc == '\\' {
                // Escape next char
                if px + 1 < pat.len() {
                    let next = pat[px + 1];
                    if next == txt[tx] {
                        px += 2;
                        tx += 1;
                        continue;
                    } else {
                        // No match, try backtrack
                        if let (Some(spx), Some(stx)) = (star_px, star_tx) {
                            // backtrack: star matches one more char
                            px = spx + 1;
                            let new_stx = stx + 1;
                            star_tx = Some(new_stx);
                            tx = new_stx;
                            continue;
                        } else {
                            return false;
                        }
                    }
                } else {
                    // Trailing \ : treat as literal \ ?
                    if '\\' == txt[tx] {
