                            star_tx = Some(new_stx);
                            tx = new_stx;
                            continue;
                        } else {
                            return false;
                        }
                    }
                }
            } else if pc == '?' {
                // Matches single char
                px += 1;
                tx += 1;
                continue;
            } else if pc == '*' {
                // Collapse consecutive *
                while px + 1 < pat.len() && pat[px + 1] == '*' {
                    px += 1;
                }
                star_px = Some(px);
                star_tx = Some(tx);
                px += 1;
                continue;
            } else if pc == '[' {
