                        continue;
                    } else {
                        if let (Some(spx), Some(stx)) = (star_px, star_tx) {
                            px = spx + 1;
                            let new_stx = stx + 1;
                            star_tx = Some(new_stx);
                            tx = new_stx;
                            continue;
                        } else {
                            return false;
                        }
                    }
                }
            } else {
                // Literal
                if pc == txt[tx] {
                    px += 1;
                    tx += 1;
                    continue;
                } else {
                    if let (Some(spx), Some(stx)) = (star_px, star_tx) {
                        px = spx + 1;
                        let new_stx = stx + 1;
                        star_tx = Some(new_stx);
                        tx = new_stx;
                        continue;
                    } else {
                        return false;
                    }
                }
            }
        } else {
            // Pattern exhausted but text remains: backtrack if star
            if let (Some(spx), Some(stx)) = (star_px, star_tx) {
                px = spx + 1;
                let new_stx = stx + 1;
                star_tx = Some(new_stx);
                tx = new_stx;
                continue;
            } else {
                return false;
            }
        }
    }
    // Text exhausted: skip trailing * in pattern
    while px < pat.len() && pat[px] == '*' {
        px += 1;
    }
    // Handle trailing \? And [...]? If pattern remains, must be all * (already skipped) or empty
    // If remaining pattern is like [...] that can match empty? No, [] requires a char, so fail
