                                            // Actually, local tracking local? Possible via `git branch --track`? Unlikely tested. Ignore.
                                            continue;
                                        };
                                        base_locals.insert(local_name.clone());
                                        base_remotes.insert(up_short.clone());
                                        if let Ok(commit) = up.get().peel_to_commit() {
                                            base_commit_oids.push(commit.id());
                                        }
                                    }
                                    Err(e) if e.code() == git2::ErrorCode::NotFound => {
                                        // No upstream (non-tracking base): ignore (no bases for this piece, as observed)
                                        continue;
                                    }
                                    Err(e) => return Err(e.into()),
                                }
                            }
                            Err(e) => return Err(e.into()),
                        }
                    } else if full.starts_with("refs/remotes/") {
                        let remote_short = full["refs/remotes/".len()..].to_string();
                        base_remotes.insert(remote_short.clone());
                        // Get commit for base (remote itself)
                        if let Ok(commit) = resolved.peel_to_commit() {
                            base_commit_oids.push(commit.id());
                        }
                        // Find tracking locals for this remote base (for tracks_base display)
                        // Iterate all local branches, check if upstream == full
                        if let Ok(branches) = repo.branches(Some(git2::BranchType::Local)) {
                            for br in branches {
                                if let Ok((b, _)) = br {
                                    if let Ok(up) = b.upstream() {
                                        if let Some(up_full2) = up.get().name() {
                                            if up_full2 == full {
                                                if let Ok(Some(local_name)) = b.name().map(|n| n.map(|s| s.to_string())) {
                                                    // Only if not already base? Local tracking remote base is tracks_base, not base (unless also explicit local base?).
                                                    // If local is already in base_locals (e.g., via another explicit local base), keep as base (base takes precedence over tracks?).
                                                    // For now, record tracks_base, but base_locals check later will take precedence in display (base > tracks).
                                                    // Use original base string `orig` for display (as observed: "[tracks base `origin/master`]" with original)
                                                    tracks_base.entry(local_name).or_insert(orig.clone());
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    } else {
                        // Other branch? Unlikely (e.g., refs/heads/... is local, refs/remotes/... is remote, what else is branch? Possibly HEAD? But HEAD not branch.
                        // Treat as not branch? Already checked is_branch true, so must be one of above. If neither, ignore?
                        // For safety, error as not branch? Or ignore?
                        // Let's ignore.
                        continue;
                    }
                }
            }
        }
        BasesSource::Config(pieces) => {
            // Same as CLI non-empty (no fallback, since empty already errored before fetch)
            for orig in pieces {
                let resolved = match repo.resolve_reference_from_short_name(orig) {
                    Ok(r) => r,
                    Err(e) => {
                        if e.code() == git2::ErrorCode::NotFound {
                            continue;
                        } else {
                            return Err(e.into());
                        }
                    }
                };
                if !resolved.is_branch() {
                    let full_name = resolved.name().unwrap_or(orig.as_str()).to_string();
                    return Err(anyhow!("Reference Some(\"{}\") is not a branch", full_name));
                }
                let full = resolved.name().unwrap_or("").to_string();
                if full.starts_with("refs/heads/") {
                    let local_name = full["refs/heads/".len()..].to_string();
                    match repo.find_branch(&local_name, git2::BranchType::Local) {
                        Ok(b) => {
                            match b.upstream() {
                                Ok(up) => {
                                    let up_full = up.get().name().unwrap_or("").to_string();
                                    let up_short = if up_full.starts_with("refs/remotes/") {
                                        up_full["refs/remotes/".len()..].to_string()
                                    } else {
                                        continue;
                                    };
                                    base_locals.insert(local_name.clone());
                                    base_remotes.insert(up_short.clone());
                                    if let Ok(commit) = up.get().peel_to_commit() {
                                        base_commit_oids.push(commit.id());
                                    }
                                }
                                Err(e) if e.code() == git2::ErrorCode::NotFound => continue,
                                Err(e) => return Err(e.into()),
                            }
                        }
                        Err(e) => return Err(e.into()),
                    }
                } else if full.starts_with("refs/remotes/") {
                    let remote_short = full["refs/remotes/".len()..].to_string();
                    base_remotes.insert(remote_short.clone());
                    if let Ok(commit) = resolved.peel_to_commit() {
                        base_commit_oids.push(commit.id());
                    }
                    if let Ok(branches) = repo.branches(Some(git2::BranchType::Local)) {
                        for br in branches {
                            if let Ok((b, _)) = br {
                                if let Ok(up) = b.upstream() {
                                    if let Some(up_full2) = up.get().name() {
                                        if up_full2 == full {
                                            if let Ok(Some(local_name)) = b.name().map(|n| n.map(|s| s.to_string())) {
                                                tracks_base.entry(local_name).or_insert(orig.clone());
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                } else {
                    continue;
                }
            }
        }
        BasesSource::Auto => {
            // Use auto_head_targets (already collected before fetch, but need to re-resolve after fetch? HEADs may have changed after fetch? Unlikely (fetch doesn't change HEAD symrefs). Good: use collected.
            // For each head target, find tracking locals
            for head_target in &auto_head_targets {
                // head_target is like refs/remotes/origin/master
                let remote_short = if head_target.starts_with("refs/remotes/") {
                    head_target["refs/remotes/".len()..].to_string()
                } else {
                    continue;
                };
                // Find locals tracking this
                if let Ok(branches) = repo.branches(Some(git2::BranchType::Local)) {
                    for br in branches {
                        if let Ok((b, _)) = br {
                            if let Ok(up) = b.upstream() {
                                if let Some(up_full) = up.get().name() {
                                    if up_full == head_target {
                                        if let Ok(Some(local_name)) = b.name().map(|n| n.map(|s| s.to_string())) {
                                            base_locals.insert(local_name.clone());
                                            base_remotes.insert(remote_short.clone());
                                            // Get commit for base (upstream commit)
                                            if let Ok(commit) = up.get().peel_to_commit() {
                                                // Avoid duplicates? Use Vec, dedupe later? For merged checks, duplicates fine.
                                                base_commit_oids.push(commit.id());
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                // Note: if no local tracks this HEAD, then no base for this remote (as observed: upstream/master with no tracking is not base, it's *3)
            }
            // Dedupe base commits? Not necessary, but okay.
        }
    }

    // Dedupe base commits
    base_commit_oids.sort();
    base_commit_oids.dedup();

    // If explicit bases given but all ignored (e.g., -b nonexistent with no valid bases), then base sets empty (no bases, no error, no deletes for merged?).
    // That's fine (as observed: -b nonexistent gives no bases, all remain without annotations, no deletes).

    // Get HEAD branch name (for detach check) and HEAD commit? For detached HEAD, no branch.
    let head_branch_name: Option<String> = match repo.head() {
        Ok(h) => {
            if h.is_branch() {
                h.shorthand().map(|s| s.to_string())
            } else {
                None // detached
            }
        }
        Err(e) => {
            // For empty repo with explicit bases, head() fails with UnbornBranch (as observed: empty repo with -b master gives UnbornBranch error about master)
            // When does this happen? After fetch and base validation, before preview. Our base validation for explicit bases in empty repo would have...
            // For empty repo, explicit base "master" resolve would... In empty repo, resolve "master" gives UnbornBranch? Or NotFound? Let's see: empty repo has no refs, HEAD points to unborn refs/heads/master.
            // resolve_reference_from_short_name("master") in empty repo: what error? Possibly UnbornBranch (since HEAD's target is unborn? Or since no such ref, NotFound?).
            // Our earlier test showed empty repo with -b master gives UnbornBranch error about refs/heads/master (not about resolving base, but about HEAD?).
            // Actually our base validation for "master" would call resolve("master"), which in empty repo might return UnbornBranch (since master is unborn HEAD target?).
            // That would propagate as error (as observed). Good: our code already handles that (return Err(e) for UnbornBranch).
            // But what about empty repo with -b nonexistent (which should be ignored, NotFound, no error, but observed gives UnbornBranch about master, not ignored)?
            // For -b nonexistent in empty repo, resolve("nonexistent") would give NotFound (since no such ref), which we ignore (continue), resulting in no bases, no error.
            // Then later, when we try repo.head() here (for HEAD branch), it would fail with UnbornBranch (since HEAD unborn), and we would return Err (as observed: empty repo with -b nonexistent gives UnbornBranch about master).
            // Good: this head() call will produce that error for empty repo cases where bases ignored.
            // For non-empty repo, head() succeeds (even if detached, is_branch false, returns None, no error).
            // So propagate error here for empty repo.
            return Err(e.into());
        }
    };

