#[derive(Debug, Clone)]
struct DeleteSet {
    merged_local: bool,
    merged_remote_scopes: Vec<String>,
    stray: bool,
    diverged_scopes: Vec<String>,
    local: bool,
    remote_scopes: Vec<String>,
}

impl DeleteSet {
    fn has_tracking(&self) -> bool {
        self.merged_local || !self.merged_remote_scopes.is_empty() || self.stray || !self.diverged_scopes.is_empty()
    }
    fn merged_remote_covers(&self, remote: &str) -> bool {
        self.merged_remote_scopes.iter().any(|s| s == "*" || s == remote)
    }
    fn diverged_covers(&self, remote: &str) -> bool {
        self.diverged_scopes.iter().any(|s| s == "*" || s == remote)
    }
    fn remote_covers(&self, remote: &str) -> bool {
        self.remote_scopes.iter().any(|s| s == "*" || s == remote)
    }
}

fn parse_delete_pieces(pieces: &[String], is_cli: bool) -> Result<DeleteSet> {
    // pieces are already split by comma (for CLI via delimiter, for config via manual split with "" skipped?)
    // For CLI, pieces include all (including validated, no empty). For config, pieces exclude "" (already skipped), but include spaces? Validate each.
    // Actually for CLI, validation already done by clap, so just parse. For config, need to validate here.
    // To unify, validate again here (for config) and parse.
    let mut ds = DeleteSet {
        merged_local: false,
        merged_remote_scopes: Vec::new(),
        stray: false,
        diverged_scopes: Vec::new(),
        local: false,
        remote_scopes: Vec::new(),
    };
    for original in pieces {
        // For config, skip "" (exactly empty) – caller should have skipped, but double-check: if is_cli==false and original=="" then skip
        if !is_cli && original == "" {
            continue;
        }
        let trimmed = original.trim();
        if trimmed.is_empty() {
            // For CLI, this should have been caught by clap, but just in case
            // For config with " " (spaces), error with original
            return Err(anyhow!("Invalid delete range format `{}`", original));
        }
        if let Some(idx) = trimmed.find(':') {
            let range_raw = &trimmed[..idx];
            let scope_raw = &trimmed[idx+1..];
            let range = range_raw.trim();
            let scope = scope_raw.trim();
            match range {
                "merged" | "merged-remote" | "diverged" | "remote" => {
                    if scope.is_empty() {
                        return Err(anyhow!("Scope parse error for delete range while parsing scope: Scope is empty"));
                    }
                    match range {
                        "merged" => {
                            ds.merged_local = true;
                            ds.merged_remote_scopes.push(scope.to_string());
                        }
                        "merged-remote" => {
                            ds.merged_remote_scopes.push(scope.to_string());
                        }
                        "diverged" => {
                            ds.diverged_scopes.push(scope.to_string());
                        }
                        "remote" => {
                            ds.remote_scopes.push(scope.to_string());
                        }
                        _ => unreachable!(),
                    }
                }
                "merged-local" | "stray" | "local" => {
                    return Err(anyhow!("Invalid delete range format `{}`", original));
                }
                _ => {
                    return Err(anyhow!("Invalid delete range format `{}`", original));
                }
            }
        } else {
            let range = trimmed;
            match range {
                "merged-local" => ds.merged_local = true,
                "stray" => ds.stray = true,
                "local" => ds.local = true,
                "merged" | "merged-remote" | "diverged" | "remote" => {
                    return Err(anyhow!("Invalid delete range format `{}`", original));
                }
                _ => {
                    return Err(anyhow!("Invalid delete range format `{}`", original));
                }
            }
        }
    }
    Ok(ds)
}

fn main() -> Result<()> {
    let matches = build_cli().get_matches();
    let no_update = matches.get_one::<bool>("no-update").copied().unwrap_or(false);
    let update = matches.get_one::<bool>("update").copied().unwrap_or(false);
    let no_confirm = matches.get_one::<bool>("no-confirm").copied().unwrap_or(false);
    let confirm_flag = matches.get_one::<bool>("confirm").copied().unwrap_or(false);
    let no_detach = matches.get_one::<bool>("no-detach").copied().unwrap_or(false);
    let detach_flag = matches.get_one::<bool>("detach").copied().unwrap_or(false);
    let dry_run = matches.get_one::<bool>("dry-run").copied().unwrap_or(false);
    let cli_update_interval: Option<u64> = matches.get_one::<u64>("update-interval").copied();

    // Open repo
    let repo = match git2::Repository::open(".") {
        Ok(r) => r,
        Err(e) => {
            return Err(e.into());
        }
    };

    // Check remotes
    let remotes_obj = match repo.remotes() {
        Ok(r) => r,
        Err(e) => return Err(e.into()),
    };
    let mut remote_names: Vec<String> = Vec::new();
    for i in 0..remotes_obj.len() {
        if let Some(name) = remotes_obj.get(i) {
            remote_names.push(name.to_string());
        }
    }
    if remote_names.is_empty() {
        return Err(anyhow!("git-trim requires at least one remote"));
    }

    // Simultaneous check
    if update && no_update {
        eprintln!("Error: Flag 'update' and 'no-update' cannot be used simultaneously");
        std::process::exit(255);
    }
    if confirm_flag && no_confirm {
        eprintln!("Error: Flag 'confirm' and 'no-confirm' cannot be used simultaneously");
        std::process::exit(255);
    }
    if detach_flag && no_detach {
        eprintln!("Error: Flag 'detach' and 'no-detach' cannot be used simultaneously");
        std::process::exit(255);
    }

    // Parse booleans: update, confirm, detach
    // Helper to get bool config
    let get_bool_cfg = |key: &str| -> Result<Option<bool>> {
        let cfg = repo.config()?;
        match cfg.get_bool(key) {
            Ok(v) => Ok(Some(v)),
            Err(e) if e.code() == git2::ErrorCode::NotFound => Ok(None),
            Err(e) => Err(e.into()),
        }
    };

    let cfg_update = get_bool_cfg("trim.update")?;
    let do_update: bool = if no_update {
        false
    } else if update {
        true
    } else if let Some(v) = cfg_update {
        v
    } else {
        true
    };

    let cfg_confirm = get_bool_cfg("trim.confirm")?;
    let do_confirm: bool = if no_confirm {
        false
    } else if confirm_flag {
        true
    } else if let Some(v) = cfg_confirm {
        v
    } else {
        true
    };

    let cfg_detach = get_bool_cfg("trim.detach")?;
    let do_detach: bool = if no_detach {
        false
    } else if detach_flag {
        true
    } else if let Some(v) = cfg_detach {
        v
    } else {
        true
    };

    // Parse update interval (validates, panics if negative, but value ignored for fetching)
    let _update_interval: u64 = config::get_update_interval(&repo, cli_update_interval)?;

    // Parse delete
    let cli_delete_pieces: Option<Vec<String>> = matches.get_many::<String>("delete").map(|vals| vals.cloned().collect());
    let delete_set: DeleteSet = if let Some(pieces) = cli_delete_pieces {
        // CLI already validated per piece via clap, but need to parse into set
        // pieces are already split by delimiter (each piece is single range, no comma)
        // However, pieces may contain spaces (e.g., " merged:origin "), need to trim for parsing (already handled in parse)
        parse_delete_pieces(&pieces, true)?
    } else {
        // Try config
        let cfg = repo.config()?;
        match cfg.get_string("trim.delete") {
            Ok(s) => {
                // Split by comma, skip exactly "" pieces, validate others
                let raw_pieces: Vec<String> = s.split(',').map(|x| x.to_string()).collect();
                let mut filtered: Vec<String> = Vec::new();
                for p in raw_pieces {
                    if p == "" {
                        continue;
                    } else {
                        filtered.push(p);
                    }
                }
                // If filtered empty (e.g., config "" or ","), then empty set (delete nothing), no error
                // parse_delete_pieces with empty will give empty set
                parse_delete_pieces(&filtered, false)?
            }
            Err(e) if e.code() == git2::ErrorCode::NotFound => {
                // Default merged:origin
                parse_delete_pieces(&vec!["merged:origin".to_string()], true)?
            }
            Err(e) => return Err(e.into()),
        }
    };

    // Parse protected
    let cli_protected_vals: Option<Vec<String>> = matches.get_many::<String>("protected").map(|vals| vals.cloned().collect());
    let protected_patterns: Vec<String> = if let Some(vals) = cli_protected_vals {
        // Each val is comma-separated, split and ignore ""
        let mut pats = Vec::new();
        for v in vals {
            for piece in v.split(',') {
                if piece == "" {
                    continue;
                } else {
                    pats.push(piece.to_string());
                }
            }
        }
        pats
    } else {
        let cfg = repo.config()?;
        match cfg.get_string("trim.protected") {
            Ok(s) => {
                let mut pats = Vec::new();
                for piece in s.split(',') {
                    if piece == "" {
                        continue;
                    } else {
                        pats.push(piece.to_string());
                    }
                }
                pats
            }
            Err(e) if e.code() == git2::ErrorCode::NotFound => Vec::new(),
            Err(e) => return Err(e.into()),
        }
    };

    // Parse bases: determine source
    let cli_bases_vals: Option<Vec<String>> = matches.get_many::<String>("bases").map(|vals| vals.cloned().collect());
    enum BasesSource {
        Cli(Vec<String>), // raw pieces after split, including filtering? For CLI, need to handle empty fallback
        Config(Vec<String>), // non-empty pieces (after ignoring "", must be non-empty else error before fetch)
        Auto,
    }
    let bases_source: BasesSource;
    if let Some(vals) = cli_bases_vals {
        // CLI given (even if all empty, it overrides config and means current branch fallback if empty)
        let mut pieces: Vec<String> = Vec::new();
        for v in vals {
            for piece in v.split(',') {
                // For CLI bases, ignore exactly "" (empty), keep others (including spaces? Spaces will error later after fetch)
                if piece == "" {
                    continue;
                } else {
                    pieces.push(piece.to_string());
                }
            }
        }
        // pieces may be empty (all ""), meaning fallback to current branch (handled after fetch)
        bases_source = BasesSource::Cli(pieces);
    } else {
        // Check config
        let cfg = repo.config()?;
        match cfg.get_string("trim.bases") {
            Ok(s) => {
                let mut pieces: Vec<String> = Vec::new();
                for piece in s.split(',') {
                    if piece == "" {
                        continue;
                    } else {
                        pieces.push(piece.to_string());
                    }
                }
                if pieces.is_empty() {
                    // Config empty error before fetch (stdout empty)
                    eprintln!("I found that `git config trim.bases` is empty! Try any following commands to set valid bases:");
                    eprintln!(" * `git config trim.bases develop,master` for a repository.");
                    eprintln!(" * `git config --global trim.bases develop,master` to set globally.");
                    eprintln!(" * `git trim --bases develop,master` to set temporarily.");
                    return Err(anyhow!("No base branch is found!"));
                } else {
                    bases_source = BasesSource::Config(pieces);
                }
            }
            Err(e) if e.code() == git2::ErrorCode::NotFound => {
                bases_source = BasesSource::Auto;
            }
            Err(e) => return Err(e.into()),
        }
    }

    // For Auto, check HEADs before fetch
    // Collect HEAD targets for each remote
    let mut auto_head_targets: Vec<String> = Vec::new(); // full ref names like refs/remotes/origin/master
    let mut has_any_head = false;
    if matches!(bases_source, BasesSource::Auto) {
        for remote in &remote_names {
            let head_ref_name = format!("refs/remotes/{}/HEAD", remote);
            match repo.find_reference(&head_ref_name) {
                Ok(r) => {
                    if r.kind() == Some(git2::ReferenceType::Symbolic) {
                        if let Some(target) = r.symbolic_target() {
                            has_any_head = true;
                            auto_head_targets.push(target.to_string());
                        }
                    } else {
                        // Not symbolic, ignore (no HEAD)
                    }
                }
                Err(e) if e.code() == git2::ErrorCode::NotFound => {
                    // No HEAD for this remote, ignore
                }
                Err(e) => return Err(e.into()),
            }
        }
        if !has_any_head {
            // Error before fetch
            println!("You also can set bases manually with any of following commands:");
            if remote_names.len() == 1 {
                let remote = &remote_names[0];
                eprintln!("I can't detect base branch! Try following any resolution:");
                eprintln!(" * `git remote set-head {} --auto` will help `git-trim` to automatically", remote);
                eprintln!("   detect the base branch.");
                eprintln!("   If you see `{}/HEAD set to <base branch>` in the output of the previous", remote);
                eprintln!("   command, then `git branch --set-upstream {}/<base branch> <base branch>`", remote);
                eprintln!("   to set an upstream branch for <base branch> if exists.");
                eprintln!(" * `git config trim.bases develop,master` for a repository.");
                eprintln!(" * `git config --global trim.bases develop,master` to set globally.");
                eprintln!(" * `git trim --bases develop,master` to set temporarily.");
            } else {
                eprintln!("I can't detect base branch! Try following any resolution:");
                eprintln!(" * `git remote set-head <remote> --auto` will help `git-trim` to automatically");
                eprintln!("   detect the base branch.");
                eprintln!("   Following command will sync all remotes for you:");
                eprintln!("   `for REMOTE in $(git remote); do git remote set-head \"$REMOTE\" --auto; done`");
                eprintln!("   Pick an appropriate one in mind if you see multiple `<remote>/HEAD set to");
                eprintln!("   <base branch>` in the output of the previous command.");
                eprintln!("   Then `git branch --set-upstream <remote>/<base branch> <base branch>` to set");
                eprintln!("   an upstream branch for <base branch> if exists.");
                eprintln!(" * `git config trim.bases develop,master` for a repository.");
                eprintln!(" * `git config --global trim.bases develop,master` to set globally.");
                eprintln!(" * `git trim --bases develop,master` to set temporarily.");
            }
            return Err(anyhow!("No base branch is found!"));
        }
    }

    // Fetch phase
    if do_update {
        if dry_run {
            // Dry-run: print blank line to stdout (no actual fetch)
            println!();
        } else {
            // Non-dry: run git fetch --prune --all with inherited stdio
            let status = std::process::Command::new("git")
                .arg("fetch")
                .arg("--prune")
                .arg("--all")
                .status();
            match status {
                Ok(s) => {
                    if !s.success() {
                        let code = s.code().unwrap_or(1);
                        // Map exit code to OS error (as original does via from_raw_os_error)
                        let io_err = std::io::Error::from_raw_os_error(code);
                        return Err(anyhow!(io_err));
                    }
                }
                Err(e) => return Err(e.into()),
            }
            // Print blank line after fetch
            println!();
        }
    } else {
        // No-update: print nothing before base validation
    }

    // Now validate explicit bases (CLI or Config) after fetch, and resolve bases to commits
    // For Auto, already have head targets, need to find tracking branches
